begin;
create temp table video_fixture(a uuid,b uuid,c uuid,p uuid,q uuid);
insert into video_fixture select a.id,b.id,c.id,gen_random_uuid(),gen_random_uuid()
from public.profiles a cross join public.profiles b cross join public.profiles c
where a.id<>b.id and a.id<>c.id and b.id<>c.id and not exists(select 1 from public.friends f where (f.user_id=a.id and f.friend_id in(b.id,c.id)) or (f.friend_id=a.id and f.user_id in(b.id,c.id))) limit 1;
grant select on video_fixture to authenticated,anon;
create function pg_temp.video_assert(ok boolean,stage text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Video check failed: %',stage;end if;end$$;
select pg_temp.video_assert((select count(*)=1 from video_fixture),'fixture');
insert into public.community_posts(id,author_id,body,audience,video_path,topics) select p,a,'','friends',a::text||'/video_test.mp4',array['travel','cycling'] from video_fixture;
insert into public.community_posts(id,author_id,body,audience,video_path,topics) select q,a,'','everyone',a::text||'/video_public.mp4',array['memes'] from video_fixture;
insert into storage.objects(bucket_id,name) select 'community_videos',a::text||'/video_test.mp4' from video_fixture union all select 'community_videos',a::text||'/video_public.mp4' from video_fixture;
insert into public.friends(user_id,friend_id) select a,b from video_fixture union all select b,a from video_fixture;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select b::text from video_fixture),true);
select pg_temp.video_assert((select count(*)=2 from storage.objects where bucket_id='community_videos' and name in(select a::text||'/video_test.mp4' from video_fixture union all select a::text||'/video_public.mp4' from video_fixture)),'friend reads both videos');
select pg_temp.video_assert((select count(*)=1 from public.community_posts where id in(select p from video_fixture union all select q from video_fixture) and topics && array['cycling','running']),'topics overlap any');
select set_config('request.jwt.claim.sub',(select c::text from video_fixture),true);
select pg_temp.video_assert((select count(*)=0 from storage.objects where bucket_id='community_videos' and name=(select a::text||'/video_test.mp4' from video_fixture)),'stranger private denied');
select pg_temp.video_assert((select count(*)=1 from storage.objects where bucket_id='community_videos' and name=(select a::text||'/video_public.mp4' from video_fixture)),'stranger public allowed');
do $$begin insert into storage.objects(bucket_id,name) select 'community_videos',a::text||'/video_forged.mp4' from video_fixture;raise exception 'Foreign upload allowed';exception when insufficient_privilege then null;end$$;
select set_config('request.jwt.claim.sub',(select a::text from video_fixture),true);
insert into storage.objects(bucket_id,name) select 'community_videos',a::text||'/video_own.webm' from video_fixture;
do $$begin insert into public.community_posts(author_id,body,video_path) select a,'x',b::text||'/video_foreign.mp4' from video_fixture;raise exception 'Foreign video reference allowed';exception when check_violation then null;end$$;
do $$begin update public.community_posts set topics=array['invalid'] where id=(select p from video_fixture);raise exception 'Unknown topic allowed';exception when check_violation then null;end$$;
reset role;
update public.community_posts set moderation_hidden_at=now() where id=(select q from video_fixture);
set local role authenticated;
select set_config('request.jwt.claim.sub',(select c::text from video_fixture),true);
select pg_temp.video_assert((select count(*)=0 from storage.objects where bucket_id='community_videos' and name=(select a::text||'/video_public.mp4' from video_fixture)),'hidden video denied');
reset role;
delete from public.friends where user_id=(select b from video_fixture) and friend_id=(select a from video_fixture);
set local role authenticated;
select set_config('request.jwt.claim.sub',(select b::text from video_fixture),true);
select pg_temp.video_assert((select count(*)=0 from storage.objects where bucket_id='community_videos' and name=(select a::text||'/video_test.mp4' from video_fixture)),'ex friend denied');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
do $$begin perform pg_temp.video_assert((select count(*)=0 from storage.objects where bucket_id='community_videos'),'anonymous denied');exception when insufficient_privilege then null;end$$;
reset role;
select pg_temp.video_assert((select not public and file_size_limit=52428800 from storage.buckets where id='community_videos'),'private bucket 50MB');
select 'video topics owner/friend/stranger/anon, audience removal, moderation, provenance, overlap checks passed' as result;
rollback;
